import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position and transforms
  const { scenePosition } = config;
  if (scenePosition) {
    const pos = scenePosition.position || scenePosition;
    if (pos.x !== undefined) {
      group.position.set(pos.x, pos.y, pos.z);
    }

    if (scenePosition.rotationXYZ) {
      group.rotation.order = 'XYZ';
      const [x, y, z] = scenePosition.rotationXYZ;
      group.rotation.set(x, y, z);
    }

    if (scenePosition.scaleXYZ) {
      const [x, y, z] = scenePosition.scaleXYZ;
      group.scale.set(x, y, z);
    }
  } else {
    group.position.set(0, 1.85, 0);
  }

  // Load image texture
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearMipmapLinearFilter;

  // Plane geometry from atlas region (512×320 pixels → 1.6:1 aspect)
  const planeHeight = 1.2;
  const planeWidth = planeHeight * (512 / 320);

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text content via fontAtlas (MSDF)
  if (config.textContent && ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createTextMesh(config.textContent, {
      fontFamily: 'Lora',
      fontSize: 0.34,
      fontWeight: 400,
      align: 'center',
    });
    textMesh.position.set(0, -planeHeight / 2 - 0.3, 0.01);
    group.add(textMesh);
  }

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  group.userData.handlers = {};

  return group;
}
